BEGIN;
SET LOCAL lock_timeout='15s'; SET LOCAL statement_timeout='120s';
CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN IF to_regclass('public.office_workspaces') IS NULL OR to_regclass('public.office_memberships') IS NULL OR to_regclass('public.office_industry_spaces') IS NULL THEN RAISE EXCEPTION 'Existing Office Team schema required'; END IF; END $$;
CREATE SCHEMA IF NOT EXISTS office_private;
REVOKE ALL ON SCHEMA office_private FROM PUBLIC,anon; GRANT USAGE ON SCHEMA office_private TO authenticated;
CREATE TABLE public.office_ngo_settings(workspace_id uuid PRIMARY KEY REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,base_currency text NOT NULL DEFAULT 'TZS' CHECK(base_currency ~ '^[A-Z]{3}$'),jurisdiction text NOT NULL DEFAULT 'mainland' CHECK(jurisdiction IN ('mainland','zanzibar')),private_data_enabled boolean NOT NULL DEFAULT false,storage_review_state text NOT NULL DEFAULT 'unverified' CHECK(storage_review_state IN ('unverified','pending','approved','rejected')),storage_review_reference text,initialized boolean NOT NULL DEFAULT false,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_ngo_roles(workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,role text NOT NULL CHECK(role IN ('ngo_admin','programme_manager','finance_officer','procurement_officer','field_officer','monitoring_officer','safeguarding_officer','compliance_officer','ngo_viewer')),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE public.office_ngo_private_keys(workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,kind text NOT NULL CHECK(kind IN ('beneficiary','safeguarding')),configured boolean NOT NULL DEFAULT false,key_version integer,derivation text,iterations integer,salt bytea,nonce bytea,ciphertext bytea,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,kind),CHECK((configured=false AND salt IS NULL AND nonce IS NULL AND ciphertext IS NULL) OR (configured=true AND key_version=1 AND derivation='PBKDF2-HMAC-SHA-256/AES-256-GCM' AND iterations=600000 AND octet_length(salt)=16 AND octet_length(nonce)=12 AND octet_length(ciphertext) BETWEEN 17 AND 32768)));
CREATE TABLE public.office_ngo_idempotency(workspace_id uuid NOT NULL,actor_id uuid NOT NULL,idempotency_key uuid NOT NULL,action text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,actor_id,idempotency_key));
CREATE TABLE public.office_ngo_audit(audit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,actor_id uuid,resource text NOT NULL,action text NOT NULL,entity_id uuid,purpose text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.office_ngo_donors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),code text NOT NULL,name text NOT NULL,donor_type text NOT NULL,country_code text NOT NULL,reference text,CHECK(status IN ('active','inactive')));
CREATE INDEX office_ngo_donors_workspace_idx ON public.office_ngo_donors(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),donor_id uuid NOT NULL,code text NOT NULL,title text NOT NULL,currency text NOT NULL,award_amount numeric(24,6) NOT NULL CHECK(award_amount>0),start_on date NOT NULL,end_on date NOT NULL,restriction_reference text,CHECK(status IN ('draft','review','active','suspended','closed')));
CREATE INDEX office_ngo_grants_workspace_idx ON public.office_ngo_grants(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),grant_id uuid NOT NULL,code text NOT NULL,title text NOT NULL,region text NOT NULL,district text NOT NULL,start_on date NOT NULL,end_on date NOT NULL,CHECK(status IN ('planned','active','on_hold','completed','closed')));
CREATE INDEX office_ngo_projects_workspace_idx ON public.office_ngo_projects(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_budget_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),grant_id uuid NOT NULL,project_id uuid NOT NULL,code text NOT NULL,category text NOT NULL,amount numeric(24,6) NOT NULL CHECK(amount>0),CHECK(status IN ('draft','approved')));
CREATE INDEX office_ngo_budget_lines_workspace_idx ON public.office_ngo_budget_lines(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_disbursements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),grant_id uuid NOT NULL,code text NOT NULL,amount numeric(24,6) NOT NULL CHECK(amount>0),due_on date NOT NULL,bank_reference text,received_on date,CHECK(status IN ('scheduled','received')));
CREATE INDEX office_ngo_disbursements_workspace_idx ON public.office_ngo_disbursements(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),budget_line_id uuid NOT NULL,procurement_id uuid,subgrant_id uuid,code text NOT NULL,description text NOT NULL,amount numeric(24,6) NOT NULL CHECK(amount>0),spent_on date NOT NULL,payment_reference text,evidence_id uuid,CHECK(status IN ('draft','submitted','approved','returned','paid','cancelled')));
CREATE INDEX office_ngo_expenses_workspace_idx ON public.office_ngo_expenses(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_procurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),budget_line_id uuid NOT NULL,code text NOT NULL,description text NOT NULL,method text NOT NULL,threshold_reference text NOT NULL,amount numeric(24,6) NOT NULL CHECK(amount>0),supplier_public text NOT NULL,order_reference text,receipt_reference text,evidence_id uuid,CHECK(status IN ('draft','submitted','approved','ordered','received','closed','cancelled')));
CREATE INDEX office_ngo_procurements_workspace_idx ON public.office_ngo_procurements(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_partners(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),code text NOT NULL,legal_name text NOT NULL,registration_reference text,jurisdiction text NOT NULL,risk_rating text NOT NULL,due_diligence_on date,CHECK(status IN ('pending','approved','suspended','closed')));
CREATE INDEX office_ngo_partners_workspace_idx ON public.office_ngo_partners(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_subgrants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),partner_id uuid NOT NULL,budget_line_id uuid NOT NULL,code text NOT NULL,title text NOT NULL,amount numeric(24,6) NOT NULL CHECK(amount>0),report_due_on date NOT NULL,CHECK(status IN ('draft','approved','active','suspended','closed')));
CREATE INDEX office_ngo_subgrants_workspace_idx ON public.office_ngo_subgrants(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid NOT NULL,code text NOT NULL,title text NOT NULL,due_on date NOT NULL,owner_id uuid NOT NULL,target_quantity numeric(24,6) NOT NULL CHECK(target_quantity>=0),actual_quantity numeric(24,6) NOT NULL DEFAULT 0 CHECK(actual_quantity>=0),evidence_id uuid,CHECK(status IN ('planned','in_progress','completed','cancelled')));
CREATE INDEX office_ngo_activities_workspace_idx ON public.office_ngo_activities(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_indicators(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid NOT NULL,code text NOT NULL,title text NOT NULL,unit text NOT NULL,baseline numeric(24,6) NOT NULL,target numeric(24,6) NOT NULL,frequency text NOT NULL,CHECK(status IN ('active','archived')));
CREATE INDEX office_ngo_indicators_workspace_idx ON public.office_ngo_indicators(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_measurements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),indicator_id uuid NOT NULL,period_start date NOT NULL,period_end date NOT NULL,value numeric(24,6) NOT NULL,disaggregation text,evidence_id uuid,CHECK(status IN ('draft','verified','returned')));
CREATE INDEX office_ngo_measurements_workspace_idx ON public.office_ngo_measurements(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_beneficiaries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid NOT NULL,code text NOT NULL,cohort text NOT NULL,lawful_basis text NOT NULL,notice_reference text NOT NULL,retention_until date NOT NULL,CHECK(status IN ('enrolled','exited','withdrawn')));
CREATE INDEX office_ngo_beneficiaries_workspace_idx ON public.office_ngo_beneficiaries(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_beneficiary_private(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),beneficiary_id uuid NOT NULL,nonce bytea NOT NULL,ciphertext bytea NOT NULL,CHECK(status IN ('active','withdrawn')));
CREATE INDEX office_ngo_beneficiary_private_workspace_idx ON public.office_ngo_beneficiary_private(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_safeguarding(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid NOT NULL,code text NOT NULL,reference text,priority text NOT NULL,nonce bytea NOT NULL,ciphertext bytea NOT NULL,retention_until date NOT NULL,CHECK(status IN ('open','assessed','referred','closed')));
CREATE INDEX office_ngo_safeguarding_workspace_idx ON public.office_ngo_safeguarding(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid NOT NULL,user_id uuid NOT NULL,staff_code text NOT NULL,staff_type text NOT NULL CHECK(staff_type IN ('employee','volunteer')),position text NOT NULL,training_due_on date NOT NULL,CHECK(status IN ('active','inactive')));
CREATE INDEX office_ngo_staff_assignments_workspace_idx ON public.office_ngo_staff_assignments(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid,code text NOT NULL,name text NOT NULL,category text NOT NULL,serial_reference text NOT NULL,custodian_id uuid,acquired_on date NOT NULL,cost numeric(24,6) NOT NULL CHECK(cost>=0),condition text NOT NULL,next_service_on date,CHECK(status IN ('in_service','maintenance','retired')));
CREATE INDEX office_ngo_assets_workspace_idx ON public.office_ngo_assets(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_obligations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),jurisdiction text NOT NULL,kind text NOT NULL CHECK(kind IN ('registration','particulars_change','annual_return','funding_contract','tax','donor_report','privacy','other')),period_start date NOT NULL,period_end date NOT NULL,due_on date NOT NULL,title text NOT NULL,authority_url text NOT NULL,submission_reference text,evidence_id uuid,CHECK(status IN ('open','prepared','filed','returned')));
CREATE INDEX office_ngo_obligations_workspace_idx ON public.office_ngo_obligations(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_governance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),code text NOT NULL,title text NOT NULL,meeting_on date NOT NULL,meeting_type text NOT NULL,decision_reference text,action_owner_id uuid NOT NULL,due_on date NOT NULL,CHECK(status IN ('planned','held','actions_closed')));
CREATE INDEX office_ngo_governance_workspace_idx ON public.office_ngo_governance(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid,grant_id uuid,entity_resource text,entity_id uuid,description text NOT NULL,file_id uuid,reference text,source_url text,CHECK(status IN ('recorded','withdrawn')));
CREATE INDEX office_ngo_evidence_workspace_idx ON public.office_ngo_evidence(workspace_id,status,updated_at DESC,id);
CREATE TABLE public.office_ngo_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.office_workspaces(id) ON DELETE RESTRICT,status text NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),project_id uuid,grant_id uuid,code text NOT NULL,title text NOT NULL,report_type text NOT NULL,period_start date NOT NULL,period_end date NOT NULL,submission_reference text,evidence_id uuid,snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,CHECK(status IN ('draft','submitted','accepted','returned')));
CREATE INDEX office_ngo_reports_workspace_idx ON public.office_ngo_reports(workspace_id,status,updated_at DESC,id);
ALTER TABLE public.office_ngo_donors ADD CONSTRAINT office_ngo_donors_workspace_id_unique UNIQUE(workspace_id,id);
