ALTER TABLE public.office_ngo_budget_lines ADD CONSTRAINT ngo_budget_grant_fk FOREIGN KEY(workspace_id,grant_id) REFERENCES public.office_ngo_grants(workspace_id,id) ON DELETE RESTRICT;
ALTER TABLE public.office_ngo_budget_lines ADD CONSTRAINT ngo_budget_project_fk FOREIGN KEY(workspace_id,project_id) REFERENCES public.office_ngo_projects(workspace_id,id) ON DELETE RESTRICT;
