ALTER TABLE public.office_ngo_expenses ADD CONSTRAINT ngo_exp_budget_fk FOREIGN KEY(workspace_id,budget_line_id) REFERENCES public.office_ngo_budget_lines(workspace_id,id) ON DELETE RESTRICT;
ALTER TABLE public.office_ngo_procurements ADD CONSTRAINT ngo_proc_budget_fk FOREIGN KEY(workspace_id,budget_line_id) REFERENCES public.office_ngo_budget_lines(workspace_id,id) ON DELETE RESTRICT;
