CREATE OR REPLACE FUNCTION office_private.ngo_caps(r text) RETURNS jsonb LANGUAGE sql IMMUTABLE AS $$ SELECT CASE r
WHEN 'ngo_admin' THEN '{"manage":true,"programmes":true,"finance":true,"approve_finance":true,"procurement":true,"delivery":true,"monitoring":true,"beneficiary_private":false,"safeguarding":false,"people_assets":true,"compliance":true,"reports":true,"audit":true}'::jsonb
WHEN 'programme_manager' THEN '{"manage":false,"programmes":true,"finance":false,"approve_finance":false,"procurement":false,"delivery":true,"monitoring":true,"beneficiary_private":false,"safeguarding":false,"people_assets":true,"compliance":false,"reports":true,"audit":false}'::jsonb
WHEN 'finance_officer' THEN '{"manage":false,"programmes":false,"finance":true,"approve_finance":true,"procurement":false,"delivery":false,"monitoring":false,"beneficiary_private":false,"safeguarding":false,"people_assets":false,"compliance":false,"reports":true,"audit":false}'::jsonb
WHEN 'procurement_officer' THEN '{"manage":false,"programmes":false,"finance":false,"approve_finance":false,"procurement":true,"delivery":false,"monitoring":false,"beneficiary_private":false,"safeguarding":false,"people_assets":false,"compliance":false,"reports":false,"audit":false}'::jsonb
WHEN 'field_officer' THEN '{"manage":false,"programmes":false,"finance":false,"approve_finance":false,"procurement":false,"delivery":true,"monitoring":false,"beneficiary_private":true,"safeguarding":false,"people_assets":false,"compliance":false,"reports":false,"audit":false}'::jsonb
WHEN 'monitoring_officer' THEN '{"manage":false,"programmes":false,"finance":false,"approve_finance":false,"procurement":false,"delivery":false,"monitoring":true,"beneficiary_private":false,"safeguarding":false,"people_assets":false,"compliance":false,"reports":true,"audit":false}'::jsonb
WHEN 'safeguarding_officer' THEN '{"manage":false,"programmes":false,"finance":false,"approve_finance":false,"procurement":false,"delivery":false,"monitoring":false,"beneficiary_private":true,"safeguarding":true,"people_assets":false,"compliance":false,"reports":false,"audit":false}'::jsonb
WHEN 'compliance_officer' THEN '{"manage":false,"programmes":false,"finance":false,"approve_finance":false,"procurement":false,"delivery":false,"monitoring":false,"beneficiary_private":false,"safeguarding":false,"people_assets":false,"compliance":true,"reports":true,"audit":true}'::jsonb
ELSE '{"manage":false,"programmes":false,"finance":false,"approve_finance":false,"procurement":false,"delivery":false,"monitoring":false,"beneficiary_private":false,"safeguarding":false,"people_assets":false,"compliance":false,"reports":true,"audit":false}'::jsonb END $$;
CREATE OR REPLACE FUNCTION office_private.ngo_context(w uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN IF auth.uid() IS NULL OR NOT office_private.is_active_member(w) OR NOT EXISTS(SELECT 1 FROM public.office_industry_spaces WHERE workspace_id=w AND industry_id='ngo') THEN RAISE EXCEPTION 'NGO workspace access denied' USING ERRCODE='42501'; END IF; IF office_private.is_admin(w) THEN RETURN 'ngo_admin'; END IF; SELECT role INTO r FROM public.office_ngo_roles WHERE workspace_id=w AND user_id=auth.uid() AND active; RETURN coalesce(r,'unassigned'); END$$;
CREATE OR REPLACE FUNCTION office_private.ngo_resource_cap(r text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE r WHEN 'donors' THEN 'programmes' WHEN 'grants' THEN 'programmes' WHEN 'projects' THEN 'programmes' WHEN 'budget_lines' THEN 'finance' WHEN 'disbursements' THEN 'finance' WHEN 'expenses' THEN 'finance' WHEN 'procurements' THEN 'procurement' WHEN 'partners' THEN 'programmes' WHEN 'subgrants' THEN 'programmes' WHEN 'activities' THEN 'delivery' WHEN 'indicators' THEN 'monitoring' WHEN 'measurements' THEN 'monitoring' WHEN 'beneficiaries' THEN 'delivery' WHEN 'beneficiary_private' THEN 'beneficiary_private' WHEN 'safeguarding' THEN 'safeguarding' WHEN 'staff_assignments' THEN 'people_assets' WHEN 'assets' THEN 'people_assets' WHEN 'obligations' THEN 'compliance' WHEN 'governance' THEN 'compliance' WHEN 'evidence' THEN 'compliance' WHEN 'reports' THEN 'reports' ELSE NULL END $$;
CREATE OR REPLACE FUNCTION office_private.ngo_allow(r text,k text) RETURNS boolean LANGUAGE sql IMMUTABLE AS $$ SELECT k = ANY(CASE r
WHEN 'donors' THEN ARRAY['code','name','donor_type','country_code','reference'] WHEN 'grants' THEN ARRAY['donor_id','code','title','currency','award_amount','start_on','end_on','restriction_reference'] WHEN 'projects' THEN ARRAY['grant_id','code','title','region','district','start_on','end_on'] WHEN 'budget_lines' THEN ARRAY['grant_id','project_id','code','category','amount'] WHEN 'disbursements' THEN ARRAY['grant_id','code','amount','due_on','bank_reference','received_on'] WHEN 'expenses' THEN ARRAY['budget_line_id','procurement_id','subgrant_id','code','description','amount','spent_on','payment_reference','evidence_id'] WHEN 'procurements' THEN ARRAY['budget_line_id','code','description','method','threshold_reference','amount','supplier_public','order_reference','receipt_reference','evidence_id'] WHEN 'partners' THEN ARRAY['code','legal_name','registration_reference','jurisdiction','risk_rating','due_diligence_on'] WHEN 'subgrants' THEN ARRAY['partner_id','budget_line_id','code','title','amount','report_due_on'] WHEN 'activities' THEN ARRAY['project_id','code','title','due_on','owner_id','target_quantity','actual_quantity','evidence_id'] WHEN 'indicators' THEN ARRAY['project_id','code','title','unit','baseline','target','frequency'] WHEN 'measurements' THEN ARRAY['indicator_id','period_start','period_end','value','disaggregation','evidence_id'] WHEN 'beneficiaries' THEN ARRAY['project_id','code','cohort','lawful_basis','notice_reference','retention_until'] WHEN 'beneficiary_private' THEN ARRAY['beneficiary_id','nonce','ciphertext'] WHEN 'safeguarding' THEN ARRAY['project_id','code','reference','priority','nonce','ciphertext','retention_until'] WHEN 'staff_assignments' THEN ARRAY['project_id','user_id','staff_code','staff_type','position','training_due_on'] WHEN 'assets' THEN ARRAY['project_id','code','name','category','serial_reference','custodian_id','acquired_on','cost','condition','next_service_on'] WHEN 'obligations' THEN ARRAY['jurisdiction','kind','period_start','period_end','due_on','title','authority_url','submission_reference','evidence_id'] WHEN 'governance' THEN ARRAY['code','title','meeting_on','meeting_type','decision_reference','action_owner_id','due_on'] WHEN 'evidence' THEN ARRAY['project_id','grant_id','entity_resource','entity_id','description','file_id','reference','source_url'] WHEN 'reports' THEN ARRAY['project_id','grant_id','code','title','report_type','period_start','period_end','submission_reference','evidence_id'] ELSE ARRAY[]::text[] END) $$;
CREATE OR REPLACE FUNCTION office_private.ngo_project_allowed(p_workspace_id uuid,p_project_id uuid,p_role text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT p_project_id IS NOT NULL AND (p_role IN ('ngo_admin','programme_manager','finance_officer','procurement_officer','compliance_officer','ngo_viewer') OR EXISTS (SELECT 1 FROM public.office_ngo_staff_assignments a WHERE a.workspace_id=p_workspace_id AND a.project_id=p_project_id AND a.user_id=auth.uid() AND a.status='active'))
$$;
CREATE OR REPLACE FUNCTION office_private.ngo_column_type(p_resource text,p_key text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT CASE WHEN p_key IN ('donor_id','grant_id','project_id','budget_line_id','procurement_id','subgrant_id','partner_id','indicator_id','beneficiary_id','owner_id','user_id','custodian_id','action_owner_id','entity_id','file_id','evidence_id') THEN 'uuid' WHEN p_key IN ('award_amount','amount','target_quantity','actual_quantity','baseline','target','value','cost') THEN 'numeric' WHEN p_key IN ('start_on','end_on','due_on','received_on','spent_on','report_due_on','training_due_on','retention_until','acquired_on','next_service_on','period_start','period_end','meeting_on','due_on','due_on') THEN 'date' ELSE 'text' END
$$;
CREATE OR REPLACE FUNCTION office_private.ngo_evidence_target_exists(p_workspace_id uuid,p_resource text,p_id uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE ok boolean;
BEGIN
 IF p_resource NOT IN ('donors','grants','projects','budget_lines','disbursements','expenses','procurements','partners','subgrants','activities','indicators','measurements','beneficiaries','staff_assignments','assets','obligations','governance','evidence','reports') THEN RETURN false; END IF;
 EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.office_ngo_%I WHERE workspace_id=$1 AND id=$2)',p_resource) INTO ok USING p_workspace_id,p_id;
 RETURN ok;
END$$;
CREATE OR REPLACE FUNCTION office_private.ngo_validate_record(p_workspace_id uuid,p_resource text,p_data jsonb,p_role text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE pid uuid; gid uuid; bid uuid; iid uuid; blid uuid; prjid uuid; uid uuid; x uuid; r text;
BEGIN
 IF p_resource='grants' THEN IF NOT EXISTS(SELECT 1 FROM public.office_ngo_donors d WHERE d.workspace_id=p_workspace_id AND d.id=(p_data->>'donor_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace donor required' USING ERRCODE='23503'; END IF;
 ELSIF p_resource='projects' THEN SELECT g.id INTO gid FROM public.office_ngo_grants g WHERE g.workspace_id=p_workspace_id AND g.id=(p_data->>'grant_id')::uuid; IF gid IS NULL THEN RAISE EXCEPTION 'Same-workspace grant required' USING ERRCODE='23503'; END IF;
 ELSIF p_resource IN ('budget_lines','disbursements') THEN IF p_resource='budget_lines' THEN gid:=(p_data->>'grant_id')::uuid; pid:=(p_data->>'project_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_projects p WHERE p.workspace_id=p_workspace_id AND p.id=pid AND p.grant_id=gid) THEN RAISE EXCEPTION 'Project and grant must match workspace' USING ERRCODE='23503'; END IF; ELSE gid:=(p_data->>'grant_id')::uuid; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_grants g WHERE g.workspace_id=p_workspace_id AND g.id=gid) THEN RAISE EXCEPTION 'Same-workspace grant required' USING ERRCODE='23503'; END IF;
 ELSIF p_resource IN ('expenses','procurements','subgrants') THEN blid:=(p_data->>'budget_line_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND b.id=blid) THEN RAISE EXCEPTION 'Same-workspace budget line required' USING ERRCODE='23503'; END IF; IF p_resource='expenses' AND p_data ? 'procurement_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_procurements q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'procurement_id')::uuid AND q.budget_line_id=blid) THEN RAISE EXCEPTION 'Procurement must match budget line' USING ERRCODE='23503'; END IF; IF p_resource='expenses' AND p_data ? 'subgrant_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_subgrants q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'subgrant_id')::uuid AND q.budget_line_id=blid) THEN RAISE EXCEPTION 'Subgrant must match budget line' USING ERRCODE='23503'; END IF; IF p_resource='subgrants' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_partners q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'partner_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace partner required' USING ERRCODE='23503'; END IF;
 ELSIF p_resource='staff_assignments' THEN pid:=(p_data->>'project_id')::uuid; uid:=(p_data->>'user_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_projects p WHERE p.workspace_id=p_workspace_id AND p.id=pid) THEN RAISE EXCEPTION 'Same-workspace project required' USING ERRCODE='23503'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=uid AND m.status='active') THEN RAISE EXCEPTION 'Active Office Team member required' USING ERRCODE='42501'; END IF; IF p_role IN ('field_officer','monitoring_officer','safeguarding_officer') AND NOT office_private.ngo_project_allowed(p_workspace_id,pid,p_role) THEN RAISE EXCEPTION 'Active project assignment required' USING ERRCODE='42501'; END IF;
 ELSIF p_resource IN ('activities','indicators','beneficiaries','safeguarding') THEN pid:=(p_data->>'project_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_projects p WHERE p.workspace_id=p_workspace_id AND p.id=pid) THEN RAISE EXCEPTION 'Same-workspace project required' USING ERRCODE='23503'; END IF; IF p_role IN ('field_officer','monitoring_officer','safeguarding_officer') AND NOT office_private.ngo_project_allowed(p_workspace_id,pid,p_role) THEN RAISE EXCEPTION 'Active project assignment required' USING ERRCODE='42501'; END IF;
 ELSIF p_resource='measurements' THEN iid:=(p_data->>'indicator_id')::uuid; SELECT i.project_id INTO pid FROM public.office_ngo_indicators i WHERE i.workspace_id=p_workspace_id AND i.id=iid; IF pid IS NULL THEN RAISE EXCEPTION 'Same-workspace indicator required' USING ERRCODE='23503'; END IF; IF p_role IN ('field_officer','monitoring_officer','safeguarding_officer') AND NOT office_private.ngo_project_allowed(p_workspace_id,pid,p_role) THEN RAISE EXCEPTION 'Active project assignment required' USING ERRCODE='42501'; END IF;
 ELSIF p_resource='beneficiary_private' THEN bid:=(p_data->>'beneficiary_id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_beneficiaries b WHERE b.workspace_id=p_workspace_id AND b.id=bid) THEN RAISE EXCEPTION 'Same-workspace beneficiary required' USING ERRCODE='23503'; END IF; IF p_data ? 'id' AND (p_data->>'id')::uuid<>bid THEN RAISE EXCEPTION 'Private envelope id must equal beneficiary_id' USING ERRCODE='22023'; END IF;

 ELSIF p_resource='assets' THEN IF p_data ? 'project_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_projects q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'project_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace project required' USING ERRCODE='23503'; END IF; IF p_data ? 'custodian_id' AND NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=(p_data->>'custodian_id')::uuid AND m.status='active') THEN RAISE EXCEPTION 'Active custodian required' USING ERRCODE='42501'; END IF;
 ELSIF p_resource='governance' THEN IF NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=(p_data->>'action_owner_id')::uuid AND m.status='active') THEN RAISE EXCEPTION 'Active action owner required' USING ERRCODE='42501'; END IF;
 ELSIF p_resource='reports' THEN IF p_data ? 'project_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_projects q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'project_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace report project required' USING ERRCODE='23503'; END IF; IF p_data ? 'grant_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_grants q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'grant_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace report grant required' USING ERRCODE='23503'; END IF;
 ELSIF p_resource='evidence' THEN IF p_data ? 'entity_resource' AND p_data->>'entity_resource' NOT IN ('donors','grants','projects','budget_lines','disbursements','expenses','procurements','partners','subgrants','activities','indicators','measurements','beneficiaries','staff_assignments','assets','obligations','governance','evidence','reports') THEN RAISE EXCEPTION 'Evidence target resource is not allowed' USING ERRCODE='22023'; END IF; IF p_data ? 'entity_resource' OR p_data ? 'entity_id' THEN IF NOT (p_data ? 'entity_resource' AND p_data ? 'entity_id') OR NOT office_private.ngo_evidence_target_exists(p_workspace_id,p_data->>'entity_resource',(p_data->>'entity_id')::uuid) THEN RAISE EXCEPTION 'Evidence target must exist in workspace' USING ERRCODE='23503'; END IF; END IF; IF p_data ? 'project_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_projects q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'project_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace evidence project required' USING ERRCODE='23503'; END IF; IF p_data ? 'grant_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_grants q WHERE q.workspace_id=p_workspace_id AND q.id=(p_data->>'grant_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace evidence grant required' USING ERRCODE='23503'; END IF; IF p_data ? 'file_id' AND to_regclass('public.office_cloud_files') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.office_cloud_files f WHERE f.workspace_id=p_workspace_id AND f.file_id=(p_data->>'file_id')::uuid AND f.deleted_at IS NULL AND EXISTS(SELECT 1 FROM public.office_cloud_revisions v WHERE v.workspace_id=f.workspace_id AND v.file_id=f.file_id AND v.state='available')) THEN RAISE EXCEPTION 'Evidence file must be an available active cloud file' USING ERRCODE='23503'; END IF;
 END IF;
 IF p_resource <> 'evidence' AND p_data ? 'evidence_id' AND NOT EXISTS(SELECT 1 FROM public.office_ngo_evidence e WHERE e.workspace_id=p_workspace_id AND e.id=(p_data->>'evidence_id')::uuid) THEN RAISE EXCEPTION 'Same-workspace evidence required' USING ERRCODE='23503'; END IF;
 IF p_resource='activities' AND NOT EXISTS(SELECT 1 FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.user_id=(p_data->>'owner_id')::uuid AND m.status='active') THEN RAISE EXCEPTION 'Active activity owner required' USING ERRCODE='42501'; END IF;
END$$;
CREATE OR REPLACE FUNCTION office_private.ngo_budget_used(p_workspace_id uuid,p_budget_line_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT coalesce((SELECT sum(amount) FROM public.office_ngo_procurements q WHERE q.workspace_id=p_workspace_id AND q.budget_line_id=p_budget_line_id AND q.status IN ('approved','ordered','received','closed')),0)+coalesce((SELECT sum(e.amount) FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.budget_line_id=p_budget_line_id AND e.procurement_id IS NULL AND e.status IN ('submitted','approved','paid')),0)
$$;
CREATE OR REPLACE FUNCTION public.office_ngo_read(p_workspace_id uuid,p_resource text,p_filter jsonb DEFAULT '{}'::jsonb,p_limit integer DEFAULT 100,p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text; caps jsonb; total bigint; rows jsonb; sql text; purpose text; s record; k text; BEGIN role:=office_private.ngo_context(p_workspace_id); IF p_limit NOT BETWEEN 1 AND 100 OR p_offset<0 OR jsonb_typeof(p_filter)<>'object' THEN RAISE EXCEPTION 'Invalid NGO read request' USING ERRCODE='22023'; END IF; IF p_resource='bootstrap' THEN SELECT * INTO s FROM public.office_ngo_settings WHERE workspace_id=p_workspace_id; RETURN jsonb_build_object('actor_id',auth.uid(),'role',role,'capabilities',office_private.ngo_caps(role),'summary',jsonb_build_object(),'settings',jsonb_build_object('base_currency',coalesce(s.base_currency,'TZS'),'jurisdiction',coalesce(s.jurisdiction,'mainland'),'private_data_enabled',coalesce(s.private_data_enabled,false),'storage_review_state',coalesce(s.storage_review_state,'unverified'),'version',coalesce(s.version,1),'initialized',coalesce(s.initialized,false))); END IF; IF p_resource='private_keys' THEN IF role NOT IN ('ngo_admin','compliance_officer') THEN RAISE EXCEPTION 'NGO key access denied' USING ERRCODE='42501'; END IF; SELECT jsonb_build_object('beneficiary',coalesce((SELECT jsonb_build_object('configured',configured,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',encode(salt,'base64'),'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64')) FROM public.office_ngo_private_keys WHERE workspace_id=p_workspace_id AND kind='beneficiary'),'{"configured":false}'::jsonb),'safeguarding',coalesce((SELECT jsonb_build_object('configured',configured,'key_version',key_version,'derivation',derivation,'iterations',iterations,'salt',encode(salt,'base64'),'nonce',encode(nonce,'base64'),'ciphertext',encode(ciphertext,'base64')) FROM public.office_ngo_private_keys WHERE workspace_id=p_workspace_id AND kind='safeguarding'),'{"configured":false}'::jsonb)) INTO rows; RETURN rows; END IF; IF p_resource='members' THEN RETURN (SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'workspace_id',m.workspace_id,'status',m.status,'role',m.role)), '[]'::jsonb),'total_count',count(*),'limit',p_limit,'offset',p_offset,'has_more',false) FROM public.office_memberships m WHERE m.workspace_id=p_workspace_id AND m.status='active'); END IF; IF p_resource='roles' THEN RETURN (SELECT jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(r)), '[]'::jsonb),'total_count',count(*),'limit',p_limit,'offset',p_offset,'has_more',false) FROM public.office_ngo_roles r WHERE r.workspace_id=p_workspace_id); END IF; IF p_resource='audit' THEN IF NOT coalesce((office_private.ngo_caps(role)->>'audit')::boolean,false) THEN RAISE EXCEPTION 'Audit capability required' USING ERRCODE='42501'; END IF; END IF; IF p_resource NOT IN ('donors','grants','projects','budget_lines','disbursements','expenses','procurements','partners','subgrants','activities','indicators','measurements','beneficiaries','beneficiary_private','safeguarding','staff_assignments','assets','obligations','governance','evidence','reports','audit') THEN RAISE EXCEPTION 'Unknown NGO resource' USING ERRCODE='22023'; END IF; FOR k IN SELECT jsonb_object_keys(p_filter) LOOP IF k NOT IN ('id','project_id','grant_id','status','purpose') THEN RAISE EXCEPTION 'Unknown NGO filter' USING ERRCODE='22023'; END IF; END LOOP; IF p_resource<>'audit' AND NOT coalesce((office_private.ngo_caps(role)->>office_private.ngo_resource_cap(p_resource))::boolean,false) THEN RAISE EXCEPTION 'NGO capability denied' USING ERRCODE='42501'; END IF; IF p_resource IN ('beneficiary_private','safeguarding') THEN purpose:=p_filter->>'purpose'; IF p_resource='beneficiary_private' AND (NOT (p_filter ? 'id') OR (p_filter->>'id')::uuid IS NULL) THEN RAISE EXCEPTION 'Beneficiary private reads require exact id' USING ERRCODE='22023'; END IF; IF purpose NOT IN ('direct_service','record_correction','safeguarding_response','compliance_review') THEN RAISE EXCEPTION 'Protected read purpose required' USING ERRCODE='22023'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_settings WHERE workspace_id=p_workspace_id AND private_data_enabled AND storage_review_state='approved') THEN RAISE EXCEPTION 'Private data gate is closed' USING ERRCODE='55000'; END IF; IF NOT EXISTS(SELECT 1 FROM public.office_ngo_private_keys WHERE workspace_id=p_workspace_id AND kind=CASE WHEN p_resource='beneficiary_private' THEN 'beneficiary' ELSE 'safeguarding' END AND configured) THEN RAISE EXCEPTION 'Resource-specific private key is not configured' USING ERRCODE='55000'; END IF; INSERT INTO public.office_ngo_audit(workspace_id,actor_id,resource,action,purpose) VALUES(p_workspace_id,auth.uid(),p_resource,'read',purpose); END IF; sql:=format('SELECT count(*) FROM public.office_ngo_%I WHERE workspace_id=$1',p_resource); IF p_filter ? 'id' THEN sql:=sql||format(' AND id=%L',(p_filter->>'id')::uuid); END IF; IF p_filter ? 'project_id' THEN sql:=sql||format(' AND project_id=%L',(p_filter->>'project_id')::uuid); END IF; IF p_filter ? 'grant_id' THEN sql:=sql||format(' AND grant_id=%L',(p_filter->>'grant_id')::uuid); END IF; IF p_filter ? 'status' THEN sql:=sql||format(' AND status=%L',p_filter->>'status'); END IF; EXECUTE sql INTO total USING p_workspace_id; IF p_resource='beneficiary_private' THEN sql:=format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM (SELECT id,workspace_id,status,version,beneficiary_id,encode(nonce,''base64'') nonce,encode(ciphertext,''base64'') ciphertext FROM public.office_ngo_beneficiary_private WHERE workspace_id=$1 AND id=%L LIMIT 1) x'); ELSEIF p_resource='safeguarding' AND NOT (p_filter ? 'id') THEN sql:=format('SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''workspace_id'',workspace_id,''status'',status,''version'',version,''project_id'',project_id,''code'',code,''priority'',priority,''retention_until'',retention_until)),''[]''::jsonb) FROM (SELECT id,workspace_id,status,version,project_id,code,priority,retention_until FROM public.office_ngo_safeguarding WHERE workspace_id=$1 ORDER BY updated_at DESC,id LIMIT $2 OFFSET $3) x'); ELSE sql:=format('SELECT coalesce(jsonb_agg(to_jsonb(x)),''[]''::jsonb) FROM (SELECT * FROM public.office_ngo_%I WHERE workspace_id=$1 ORDER BY updated_at DESC,id LIMIT $2 OFFSET $3) x',p_resource); END IF; EXECUTE sql INTO rows USING p_workspace_id,p_limit,p_offset; RETURN jsonb_build_object('rows',rows,'total_count',total,'limit',p_limit,'offset',p_offset,'has_more',p_offset+jsonb_array_length(rows)<total); END$$;

CREATE OR REPLACE FUNCTION public.office_ngo_command(p_workspace_id uuid,p_action text,p_payload jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE v_role text; v_caps jsonb; v_key uuid; v_hash text; v_old jsonb; v_resource text; v_id uuid; v_version bigint; v_status text; v_to text; v_data jsonb; v_k text; v_tbl text; v_fields text; v_vals text; v_set text; v_result jsonb; v_state_ok boolean; v_row_count bigint;
BEGIN
 v_role:=office_private.ngo_context(p_workspace_id); v_caps:=office_private.ngo_caps(v_role);
 IF jsonb_typeof(p_payload)<>'object' OR p_payload->>'idempotency_key' IS NULL THEN RAISE EXCEPTION 'Invalid NGO command' USING ERRCODE='22023'; END IF;
 BEGIN v_key:=(p_payload->>'idempotency_key')::uuid; EXCEPTION WHEN others THEN RAISE EXCEPTION 'Idempotency key must be UUID' USING ERRCODE='22023'; END; IF v_key IS NULL THEN RAISE EXCEPTION 'Idempotency key required' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_workspace_id::text,0));
 v_hash:=md5((p_action||':'||p_payload::text)::text);
 SELECT response INTO v_old FROM public.office_ngo_idempotency WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=v_key FOR UPDATE;
 IF v_old IS NOT NULL THEN IF (SELECT request_hash FROM public.office_ngo_idempotency WHERE workspace_id=p_workspace_id AND actor_id=auth.uid() AND idempotency_key=v_key)<>v_hash THEN RAISE EXCEPTION 'Idempotency key reused with different request' USING ERRCODE='22023'; END IF; RETURN v_old; END IF;
