 ELSIF p_action='configure_private_key' THEN IF v_role NOT IN ('ngo_admin','compliance_officer') THEN RAISE EXCEPTION 'Key configuration denied' USING ERRCODE='42501'; END IF; IF p_payload->>'kind' NOT IN ('beneficiary','safeguarding') THEN RAISE EXCEPTION 'Invalid key kind' USING ERRCODE='22023'; END IF; IF length(p_payload->>'salt')<>24 OR length(p_payload->>'nonce')<>16 OR length(p_payload->>'ciphertext')<24 OR length(p_payload->>'ciphertext')>43692 OR p_payload->>'salt' !~ '^[A-Za-z0-9+/]+={0,2}$' OR p_payload->>'nonce' !~ '^[A-Za-z0-9+/]+={0,2}$' OR p_payload->>'ciphertext' !~ '^[A-Za-z0-9+/]+={0,2}$' THEN RAISE EXCEPTION 'Canonical base64 key envelope required' USING ERRCODE='22023'; END IF; INSERT INTO public.office_ngo_private_keys(workspace_id,kind,configured,key_version,derivation,iterations,salt,nonce,ciphertext) VALUES(p_workspace_id,p_payload->>'kind',true,1,'PBKDF2-HMAC-SHA-256/AES-256-GCM',600000,decode(p_payload->>'salt','base64'),decode(p_payload->>'nonce','base64'),decode(p_payload->>'ciphertext','base64')) ON CONFLICT(workspace_id,kind) DO NOTHING; IF NOT FOUND THEN RAISE EXCEPTION 'Configured key cannot be overwritten' USING ERRCODE='55000'; END IF; v_result=jsonb_build_object('id',p_workspace_id,'version',1,'status','configured');
