   ELSE v_id:=coalesce((p_payload->>'id')::uuid,gen_random_uuid()); v_fields='id,workspace_id,status,created_by'; v_vals='$1,$2,$3,$4'; FOR v_k IN SELECT jsonb_object_keys(v_data) LOOP v_fields:=v_fields||','||quote_ident(v_k); v_vals:=v_vals||CASE WHEN v_k IN ('nonce','ciphertext') THEN format(',decode($5->>%L,''base64'')',v_k) ELSE format(',($5->>%L)::%s',v_k,office_private.ngo_column_type(v_resource,v_k)) END; END LOOP; v_status:=CASE v_resource WHEN 'donors' THEN 'active' WHEN 'grants' THEN 'draft' WHEN 'projects' THEN 'planned' WHEN 'budget_lines' THEN 'draft' WHEN 'disbursements' THEN 'scheduled' WHEN 'expenses' THEN 'draft' WHEN 'procurements' THEN 'draft' WHEN 'partners' THEN 'pending' WHEN 'subgrants' THEN 'draft' WHEN 'activities' THEN 'planned' WHEN 'indicators' THEN 'active' WHEN 'measurements' THEN 'draft' WHEN 'beneficiaries' THEN 'enrolled' WHEN 'beneficiary_private' THEN 'active' WHEN 'safeguarding' THEN 'open' WHEN 'staff_assignments' THEN 'active' WHEN 'assets' THEN 'in_service' WHEN 'obligations' THEN 'open' WHEN 'governance' THEN 'planned' WHEN 'evidence' THEN 'recorded' WHEN 'reports' THEN 'draft' END; IF v_resource='beneficiary_private' AND (NOT (v_data ? 'beneficiary_id') OR (p_payload ? 'id' AND (p_payload->>'id')::uuid<>(v_data->>'beneficiary_id')::uuid)) THEN RAISE EXCEPTION 'Beneficiary private relationship required' USING ERRCODE='22023'; END IF; EXECUTE format('INSERT INTO %s(%s) VALUES(%s) RETURNING version,status',v_tbl,v_fields,v_vals) INTO v_version,v_status USING v_id,p_workspace_id,v_status,auth.uid(),v_data; END IF;
  ELSE v_id:=(p_payload->>'id')::uuid; v_to:=p_payload->>'to_state'; IF v_to IS NULL THEN RAISE EXCEPTION 'Target state required' USING ERRCODE='22023'; END IF; EXECUTE format('SELECT version,status FROM %s WHERE workspace_id=$1 AND id=$2 FOR UPDATE',v_tbl) INTO v_version,v_status USING p_workspace_id,v_id; GET DIAGNOSTICS v_row_count = ROW_COUNT; IF v_row_count=0 OR v_version<>(p_payload->>'expected_version')::bigint THEN RAISE EXCEPTION 'Stale NGO record version' USING ERRCODE='40001'; END IF; v_state_ok:=CASE v_resource WHEN 'donors' THEN ((v_status='active' AND v_to='inactive') OR (v_status='inactive' AND v_to='active')) WHEN 'grants' THEN (v_status,v_to) IN (('draft','review'),('review','draft'),('review','active'),('active','suspended'),('suspended','active'),('active','closed'),('suspended','closed')) WHEN 'projects' THEN (v_status,v_to) IN (('planned','active'),('active','on_hold'),('on_hold','active'),('active','completed'),('completed','closed')) WHEN 'budget_lines' THEN (v_status,v_to)=('draft','approved') WHEN 'disbursements' THEN (v_status,v_to)=('scheduled','received') WHEN 'expenses' THEN (v_status,v_to) IN (('draft','submitted'),('submitted','approved'),('approved','paid'),('submitted','returned'),('returned','draft'),('draft','cancelled'),('submitted','cancelled')) WHEN 'procurements' THEN (v_status,v_to) IN (('draft','submitted'),('submitted','approved'),('approved','ordered'),('ordered','received'),('received','closed'),('draft','cancelled'),('submitted','cancelled'),('approved','cancelled')) WHEN 'partners' THEN (v_status,v_to) IN (('pending','approved'),('approved','suspended'),('approved','closed')) WHEN 'subgrants' THEN (v_status,v_to) IN (('draft','approved'),('approved','active'),('active','suspended'),('active','closed')) WHEN 'activities' THEN (v_status,v_to) IN (('planned','in_progress'),('in_progress','completed'),('in_progress','cancelled')) WHEN 'indicators' THEN (v_status,v_to)=('active','archived') WHEN 'measurements' THEN (v_status,v_to) IN (('draft','verified'),('draft','returned'),('returned','draft')) WHEN 'beneficiaries' THEN (v_status,v_to) IN (('enrolled','exited'),('enrolled','withdrawn')) WHEN 'safeguarding' THEN (v_status,v_to) IN (('open','assessed'),('assessed','referred'),('referred','closed'),('closed','open')) WHEN 'obligations' THEN (v_status,v_to) IN (('open','prepared'),('prepared','filed'),('prepared','returned'),('returned','prepared')) WHEN 'staff_assignments' THEN ((v_status='active' AND v_to='inactive') OR (v_status='inactive' AND v_to='active')) WHEN 'assets' THEN ((v_status='in_service' AND v_to='maintenance') OR (v_status='maintenance' AND v_to='in_service') OR (v_status='maintenance' AND v_to='retired')) WHEN 'governance' THEN (v_status,v_to) IN (('planned','held'),('held','actions_closed')) WHEN 'evidence' THEN (v_status,v_to)=('recorded','withdrawn') WHEN 'reports' THEN (v_status,v_to) IN (('draft','submitted'),('submitted','accepted'),('submitted','returned'),('returned','submitted')) ELSE false END; IF v_resource='budget_lines' AND v_to='approved' AND (SELECT coalesce(sum(b.amount),0) FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND b.grant_id=(SELECT grant_id FROM public.office_ngo_budget_lines WHERE workspace_id=p_workspace_id AND id=v_id) AND b.status='approved') + (SELECT amount FROM public.office_ngo_budget_lines WHERE workspace_id=p_workspace_id AND id=v_id) > (SELECT award_amount FROM public.office_ngo_grants g WHERE g.workspace_id=p_workspace_id AND g.id=(SELECT grant_id FROM public.office_ngo_budget_lines WHERE workspace_id=p_workspace_id AND id=v_id)) THEN RAISE EXCEPTION 'Approved budget exceeds grant award' USING ERRCODE='23514'; END IF; IF v_resource='disbursements' AND v_to='received' AND (SELECT coalesce(sum(d.amount),0) FROM public.office_ngo_disbursements d WHERE d.workspace_id=p_workspace_id AND d.grant_id=(SELECT grant_id FROM public.office_ngo_disbursements WHERE workspace_id=p_workspace_id AND id=v_id) AND d.status='received') + (SELECT amount FROM public.office_ngo_disbursements WHERE workspace_id=p_workspace_id AND id=v_id) > (SELECT award_amount FROM public.office_ngo_grants g WHERE g.workspace_id=p_workspace_id AND g.id=(SELECT grant_id FROM public.office_ngo_disbursements WHERE workspace_id=p_workspace_id AND id=v_id)) THEN RAISE EXCEPTION 'Received disbursements exceed grant award' USING ERRCODE='23514'; END IF; IF v_resource='expenses' AND v_to IN ('submitted','approved','paid') THEN
   IF NOT EXISTS (SELECT 1 FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND b.id=(SELECT e.budget_line_id FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.id=v_id) AND b.status='approved') OR office_private.ngo_budget_used(p_workspace_id,(SELECT e.budget_line_id FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.id=v_id)) + (SELECT e.amount FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.id=v_id) > (SELECT b.amount FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND b.id=(SELECT e.budget_line_id FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.id=v_id)) THEN RAISE EXCEPTION 'Expense commitment exceeds approved budget' USING ERRCODE='23514'; END IF;
