 IF v_resource='expenses' AND v_to='paid' THEN
   IF (SELECT coalesce(sum(e.amount),0) FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.status='paid' AND e.id<>v_id AND e.budget_line_id IN (SELECT b.id FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND b.grant_id=(SELECT bl.grant_id FROM public.office_ngo_budget_lines bl JOIN public.office_ngo_expenses ex ON ex.budget_line_id=bl.id WHERE ex.workspace_id=p_workspace_id AND ex.id=v_id))) + (SELECT e.amount FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.id=v_id) > (SELECT coalesce(sum(d.amount),0) FROM public.office_ngo_disbursements d WHERE d.workspace_id=p_workspace_id AND d.status='received' AND d.grant_id=(SELECT bl.grant_id FROM public.office_ngo_budget_lines bl JOIN public.office_ngo_expenses ex ON ex.budget_line_id=bl.id WHERE ex.workspace_id=p_workspace_id AND ex.id=v_id)) THEN RAISE EXCEPTION 'Paid expenses exceed received grant funding' USING ERRCODE='23514'; END IF;
 END IF; IF v_data ? 'evidence_id' AND (jsonb_typeof(v_data->'evidence_id')<>'string' OR NOT EXISTS(SELECT 1 FROM public.office_ngo_evidence e WHERE e.workspace_id=p_workspace_id AND e.id=(v_data->>'evidence_id')::uuid)) THEN RAISE EXCEPTION 'Same-workspace evidence required' USING ERRCODE='23503'; END IF; IF (v_resource='disbursements' AND v_to='received' AND (NOT (v_data ? 'bank_reference') OR jsonb_typeof(v_data->'bank_reference')<>'string' OR btrim(v_data->>'bank_reference')='' OR NOT (v_data ? 'received_on') OR jsonb_typeof(v_data->'received_on')<>'string')) OR (v_resource='expenses' AND v_to='paid' AND (NOT (v_data ? 'payment_reference') OR jsonb_typeof(v_data->'payment_reference')<>'string' OR btrim(v_data->>'payment_reference')='' OR NOT (v_data ? 'evidence_id') OR jsonb_typeof(v_data->'evidence_id')<>'string')) OR (v_resource='procurements' AND v_to='ordered' AND (NOT (v_data ? 'order_reference') OR jsonb_typeof(v_data->'order_reference')<>'string' OR btrim(v_data->>'order_reference')='')) OR (v_resource='procurements' AND v_to='received' AND (NOT (v_data ? 'receipt_reference') OR jsonb_typeof(v_data->'receipt_reference')<>'string' OR btrim(v_data->>'receipt_reference')='' OR NOT (v_data ? 'evidence_id') OR jsonb_typeof(v_data->'evidence_id')<>'string')) OR (v_resource='activities' AND v_to='completed' AND (NOT (v_data ? 'evidence_id') OR jsonb_typeof(v_data->'evidence_id')<>'string')) OR (v_resource='obligations' AND v_to='filed' AND (NOT (v_data ? 'submission_reference') OR jsonb_typeof(v_data->'submission_reference')<>'string' OR btrim(v_data->>'submission_reference')='' OR NOT (v_data ? 'evidence_id') OR jsonb_typeof(v_data->'evidence_id')<>'string')) OR (v_resource='reports' AND v_to='submitted' AND (NOT (v_data ? 'submission_reference') OR jsonb_typeof(v_data->'submission_reference')<>'string' OR btrim(v_data->>'submission_reference')='' OR NOT (v_data ? 'evidence_id') OR jsonb_typeof(v_data->'evidence_id')<>'string')) OR (v_resource='grants' AND v_to='active' AND (NOT (v_data ? 'restriction_reference') OR jsonb_typeof(v_data->'restriction_reference')<>'string' OR btrim(v_data->>'restriction_reference')='')) OR (v_resource='safeguarding' AND v_to='open' AND (NOT (v_data ? 'reference') OR jsonb_typeof(v_data->'reference')<>'string' OR btrim(v_data->>'reference')='')) THEN RAISE EXCEPTION 'Required transition metadata missing' USING ERRCODE='22023'; END IF; IF NOT v_state_ok THEN RAISE EXCEPTION 'Invalid NGO state transition' USING ERRCODE='22023'; END IF; IF v_to IN ('approved','active','verified','accepted','paid','filed','closed','completed') AND v_role IN ('ngo_viewer','field_officer','monitoring_officer') THEN RAISE EXCEPTION 'Approval capability denied' USING ERRCODE='42501'; END IF; IF v_resource IN ('expenses','procurements','subgrants') AND v_to IN ('approved','paid') AND v_status<>v_to AND EXISTS(SELECT 1 FROM public.office_ngo_audit a WHERE a.workspace_id=p_workspace_id AND a.entity_id=v_id AND a.actor_id=auth.uid() AND a.action='transition') THEN RAISE EXCEPTION 'Independent reviewer required' USING ERRCODE='42501'; END IF; v_data:=coalesce(p_payload->'data','{}'::jsonb); IF jsonb_typeof(v_data)<>'object' THEN RAISE EXCEPTION 'Transition data must be object' USING ERRCODE='22023'; END IF; FOR v_k IN SELECT jsonb_object_keys(v_data) LOOP IF NOT ((v_resource='disbursements' AND v_k IN ('bank_reference','received_on')) OR (v_resource='expenses' AND v_k IN ('payment_reference','evidence_id')) OR (v_resource='procurements' AND v_k IN ('order_reference','receipt_reference','evidence_id')) OR (v_resource='activities' AND v_k='evidence_id') OR (v_resource='grants' AND v_k='restriction_reference') OR (v_resource='safeguarding' AND v_k='reference') OR (v_resource IN ('obligations','reports') AND v_k IN ('submission_reference','evidence_id'))) THEN RAISE EXCEPTION 'Unknown transition field: %',v_k USING ERRCODE='22023'; END IF; END LOOP; IF v_resource='reports' AND v_to='submitted' THEN UPDATE public.office_ngo_reports r SET snapshot=jsonb_build_object('budget',coalesce((SELECT sum(b.amount) FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND (r.grant_id IS NULL OR b.grant_id=r.grant_id)),0),'actual',coalesce((SELECT sum(e.amount) FROM public.office_ngo_expenses e WHERE e.workspace_id=p_workspace_id AND e.status='paid' AND (r.project_id IS NULL OR e.budget_line_id IN (SELECT b.id FROM public.office_ngo_budget_lines b WHERE b.workspace_id=p_workspace_id AND b.project_id=r.project_id))),0),'verified_results',coalesce((SELECT jsonb_agg(jsonb_build_object('indicator_id',m.indicator_id,'period_start',m.period_start,'period_end',m.period_end,'value',m.value)) FROM public.office_ngo_measurements m WHERE m.workspace_id=p_workspace_id AND m.status='verified'),'[]'::jsonb),'activities',coalesce((SELECT count(*) FROM public.office_ngo_activities a WHERE a.workspace_id=p_workspace_id AND a.status='completed'),0)) WHERE r.id=v_id AND r.workspace_id=p_workspace_id; END IF; v_set:='status=$1'; FOR v_k IN SELECT jsonb_object_keys(v_data) LOOP v_set:=v_set||format(',%I=($4->>%L)::%s',v_k,v_k,office_private.ngo_column_type(v_resource,v_k)); END LOOP; EXECUTE format('UPDATE %s SET %s,version=version+1,updated_at=now() WHERE workspace_id=$2 AND id=$3 RETURNING version,status',v_tbl,v_set) INTO v_version,v_status USING v_to,p_workspace_id,v_id,v_data; END IF;
  INSERT INTO public.office_ngo_audit(workspace_id,actor_id,resource,action,entity_id) VALUES(p_workspace_id,auth.uid(),v_resource,p_action,v_id); v_result:=jsonb_build_object('id',v_id,'version',v_version,'status',v_status);
 ELSE RAISE EXCEPTION 'Unsupported NGO command' USING ERRCODE='22023'; END IF;
 INSERT INTO public.office_ngo_idempotency(workspace_id,actor_id,idempotency_key,action,request_hash,response) VALUES(p_workspace_id,auth.uid(),v_key,p_action,v_hash,v_result); RETURN v_result;
END$$;

DO $$ DECLARE n text; BEGIN FOREACH n IN ARRAY ARRAY['office_ngo_settings','office_ngo_roles','office_ngo_private_keys','office_ngo_idempotency','office_ngo_audit','office_ngo_donors','office_ngo_grants','office_ngo_projects','office_ngo_budget_lines','office_ngo_disbursements','office_ngo_expenses','office_ngo_procurements','office_ngo_partners','office_ngo_subgrants','office_ngo_activities','office_ngo_indicators','office_ngo_measurements','office_ngo_beneficiaries','office_ngo_beneficiary_private','office_ngo_safeguarding','office_ngo_staff_assignments','office_ngo_assets','office_ngo_obligations','office_ngo_governance','office_ngo_evidence','office_ngo_reports'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',n); EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated',n); END LOOP; END$$;
REVOKE ALL ON FUNCTION public.office_ngo_read(uuid,text,jsonb,integer,integer),public.office_ngo_command(uuid,text,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.office_ngo_read(uuid,text,jsonb,integer,integer),public.office_ngo_command(uuid,text,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION office_private.ngo_context(uuid),office_private.ngo_caps(text),office_private.ngo_allow(text,text),office_private.ngo_resource_cap(text),office_private.ngo_project_allowed(uuid,uuid,text),office_private.ngo_validate_record(uuid,text,jsonb,text),office_private.ngo_evidence_target_exists(uuid,text,uuid),office_private.ngo_budget_used(uuid,uuid),office_private.ngo_column_type(text,text) FROM PUBLIC,anon,authenticated;
COMMIT;
